/**
 * The positional-read MaxMind DB reader (src/shadow/mmdb.ts) against
 * databases generated by test/helpers/mmdb-writer.ts: no binary fixture is
 * committed, and every network is a documentation range. The reader was also
 * checked once, outside CI, against the real IPNetDB prefix file and the
 * reference Python reader (records and prefix lengths identical).
 */
import { mkdtempSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { afterAll, describe, expect, it } from "vitest";
import { MmdbError, MmdbReader, PAGE_CACHE_PAGES } from "../../src/shadow/mmdb.js";
import { buildMmdb, ipnetdbRecord, mmdbType, type MmdbWriteOptions } from "../helpers/mmdb-writer.js";

const dir = mkdtempSync(join(tmpdir(), "mmdb-test-"));
afterAll(() => rmSync(dir, { recursive: true, force: true }));
let n = 0;
function write(opts: MmdbWriteOptions): { path: string; build: ReturnType<typeof buildMmdb> } {
  const build = buildMmdb(opts);
  const path = join(dir, `db-${(n += 1)}.mmdb`);
  writeFileSync(path, build.file);
  return { path, build };
}

const NETWORKS: MmdbWriteOptions["networks"] = [
  { network: "192.0.2.0/24", record: ipnetdbRecord({ prefix: "192.0.2.0/24", prefixEntity: "Example Corp Ltd", asEntity: "Example Transit Inc", as: 64496 }) },
  { network: "198.51.100.0/24", record: ipnetdbRecord({ prefix: "198.51.100.0/24", prefixEntity: "Example Hosting LLC", asEntity: "Example Hosting LLC", as: 64497 }) },
  { network: "203.0.113.0/25", record: ipnetdbRecord({ prefix: "203.0.113.0/25", prefixEntity: "Example University", asEntity: "Example Research Network", as: 64498, bogon: true }) },
  { network: "2001:db8::/32", record: ipnetdbRecord({ prefix: "2001:db8::/32", prefixEntity: "Example Corp Ltd", asEntity: "Example Transit Inc", as: 64499 }) },
];

describe("MmdbReader: lookups", () => {
  it.each([24, 28, 32] as const)("record size %i: IPv4 and IPv6 records with their prefix lengths, not-found addresses", (recordSize) => {
    const { path } = write({ recordSize, networks: NETWORKS });
    const r = MmdbReader.open(path);
    try {
      expect(r.metadata).toMatchObject({ recordSize, ipVersion: 6, databaseType: "IPNetDB-Test", binaryFormatMajorVersion: 2, buildEpoch: 1_700_000_000 });
      const a = r.lookup("192.0.2.77");
      expect(a.prefixLength).toBe(24);
      expect(a.record).toMatchObject({ prefix: "192.0.2.0/24", prefix_entity: "Example Corp Ltd", as_entity: "Example Transit Inc", as: 64496, prefix_bogon: false, prefix_origins: [64496] });
      expect(r.lookup("198.51.100.1")).toMatchObject({ prefixLength: 24, record: { prefix_entity: "Example Hosting LLC", as: 64497 } });
      expect(r.lookup("203.0.113.5")).toMatchObject({ prefixLength: 25, record: { prefix_bogon: true, as: 64498 } });
      expect(r.lookup("2001:db8:1234::1")).toMatchObject({ prefixLength: 32, record: { prefix: "2001:db8::/32", as: 64499 } });
      // Outside every network: the record is null; the prefix length is how far the tree went.
      const miss = r.lookup("203.0.113.200");
      expect(miss.record).toBeNull();
      expect(miss.prefixLength).toBe(25);
      expect(r.lookup("192.0.3.1").record).toBeNull();
      expect(r.lookup("2001:db9::1").record).toBeNull();
      expect(r.lookup("::1").record).toBeNull();
    } finally {
      r.close();
    }
  });

  it("decodes every supported data type", () => {
    const record = {
      text: "Grüße, example",
      flag_true: true,
      flag_false: false,
      u16: mmdbType.uint16(65_535),
      u32: mmdbType.uint32(4_294_967_295),
      u64_small: mmdbType.uint64(42),
      u64_big: mmdbType.uint64(18_446_744_073_709_551_615n),
      u128: mmdbType.uint128(340_282_366_920_938_463_463_374_607_431_768_211_455n),
      i32_neg: mmdbType.int32(-12_345),
      i32_pos: mmdbType.int32(12_345),
      dbl: mmdbType.double(51.5),
      flt: mmdbType.float(1.5),
      raw: Buffer.from([1, 2, 3, 250]),
      list: ["a", mmdbType.uint16(7), { nested: [true] }],
      long_text: "x".repeat(300),
      longer_text: "y".repeat(70_000),
      zero: mmdbType.uint32(0),
    };
    const { path } = write({ networks: [{ network: "198.51.100.0/24", record }] });
    const r = MmdbReader.open(path);
    try {
      const got = r.lookup("198.51.100.9").record as Record<string, unknown>;
      expect(got).toEqual({
        text: "Grüße, example",
        flag_true: true,
        flag_false: false,
        u16: 65_535,
        u32: 4_294_967_295,
        u64_small: 42,
        u64_big: 18_446_744_073_709_551_615n,
        u128: 340_282_366_920_938_463_463_374_607_431_768_211_455n,
        i32_neg: -12_345,
        i32_pos: 12_345,
        dbl: 51.5,
        flt: 1.5,
        raw: Buffer.from([1, 2, 3, 250]),
        list: ["a", 7, { nested: [true] }],
        long_text: "x".repeat(300),
        longer_text: "y".repeat(70_000),
        zero: 0,
      });
    } finally {
      r.close();
    }
  });

  it.each([
    ["1-byte pointers", { pointerStyle: "min" as const, padding: 0 }],
    ["2-byte pointers (targets past 2048)", { pointerStyle: "min" as const, padding: 4_000 }],
    ["3-byte pointers (targets past 526336)", { pointerStyle: "min" as const, padding: 600_000 }],
    ["4-byte pointers", { pointerStyle: 3 as const, padding: 0 }],
  ])("follows %s to shared strings", (_label, opts) => {
    const { path, build } = write({ recordSize: 32, networks: NETWORKS, ...opts });
    expect(build.pointers).toBeGreaterThan(20);
    const r = MmdbReader.open(path);
    try {
      // The later records' keys and repeated values are all pointers to the first record's strings.
      expect(r.lookup("2001:db8::5").record).toMatchObject({ prefix_entity: "Example Corp Ltd", as_entity: "Example Transit Inc", allocation_cc: "XA", as: 64499 });
      expect(r.lookup("198.51.100.200").record).toMatchObject({ prefix_entity: "Example Hosting LLC", as_entity: "Example Hosting LLC" });
    } finally {
      r.close();
    }
  });

  it("an ip_version 4 database answers IPv4 and refuses IPv6", () => {
    const { path } = write({ ipVersion: 4, recordSize: 24, networks: NETWORKS.slice(0, 3) });
    const r = MmdbReader.open(path);
    try {
      expect(r.lookup("192.0.2.1")).toMatchObject({ prefixLength: 24, record: { as: 64496 } });
      expect(r.lookup("203.0.113.1")).toMatchObject({ prefixLength: 25 });
      expect(() => r.lookup("2001:db8::1")).toThrow(MmdbError);
    } finally {
      r.close();
    }
  });

  it("keeps a bounded page cache over thousands of lookups", () => {
    const { path } = write({ networks: NETWORKS, padding: 2_000_000 });
    const r = MmdbReader.open(path);
    try {
      for (let i = 0; i < 2_000; i += 1) r.lookup(`192.0.2.${i % 256}`);
      expect((r as unknown as { pages: Map<number, Buffer> }).pages.size).toBeLessThanOrEqual(PAGE_CACHE_PAGES);
    } finally {
      r.close();
    }
  });
});

describe("MmdbReader: refusals", () => {
  it("refuses a file without metadata, a non-file and unsupported metadata", () => {
    expect(() => MmdbReader.open(write({ networks: NETWORKS, omitMarker: true }).path)).toThrow(/metadata marker/);
    expect(() => MmdbReader.open(join(dir, "missing.mmdb"))).toThrow(MmdbError);
    expect(() => MmdbReader.open(write({ networks: NETWORKS, metadata: { record_size: mmdbType.uint16(20) } }).path)).toThrow(/record_size/);
    expect(() => MmdbReader.open(write({ networks: NETWORKS, metadata: { binary_format_major_version: mmdbType.uint16(3) } }).path)).toThrow(/binary format/);
    expect(() => MmdbReader.open(write({ networks: NETWORKS, metadata: { node_count: mmdbType.uint32(10_000_000) } }).path)).toThrow(/search tree/);
    const empty = join(dir, "empty.mmdb");
    writeFileSync(empty, Buffer.alloc(0));
    expect(() => MmdbReader.open(empty)).toThrow(MmdbError);
  });

  it("refuses lookups after close and non-addresses, with fixed messages", () => {
    const r = MmdbReader.open(write({ networks: NETWORKS }).path);
    expect(() => r.lookup("not an address")).toThrow(/not an address/);
    r.close();
    r.close();
    expect(r.closed).toBe(true);
    let message = "";
    try {
      r.lookup("192.0.2.1");
    } catch (e) {
      message = (e as Error).message;
    }
    expect(message).toBe("mmdb: closed");
  });

  it("refuses a record pointer outside the data section", () => {
    const { path, build } = write({ recordSize: 32, networks: [{ network: "192.0.2.0/24", record: { a: "b" } }] });
    // Corrupt the leaf record that holds 192.0.2.0/24 so it points far past the data section.
    const file = Buffer.from(build.file);
    const nodeCount = build.nodeCount;
    for (let off = 0; off < nodeCount * 8; off += 4) {
      const v = file.readUInt32BE(off);
      if (v > nodeCount) file.writeUInt32BE(nodeCount + 16 + 10_000_000, off);
    }
    writeFileSync(path, file);
    const r = MmdbReader.open(path);
    try {
      expect(() => r.lookup("192.0.2.1")).toThrow(/outside the data section/);
    } finally {
      r.close();
    }
  });
});
